import{_ as e,a,o as i,a6 as s}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Wishlist","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/shop/wishlist/index.md","filePath":"api/graphql-api/shop/wishlist/index.md","lastUpdated":1787290888000}'),o={name:"api/graphql-api/shop/wishlist/index.md"};function r(h,t,d,l,p,n){return i(),a("div",null,t[0]||(t[0]=[s('<h1 id="wishlist" tabindex="-1">Wishlist <a class="header-anchor" href="#wishlist" aria-label="Permalink to &quot;Wishlist&quot;">​</a></h1><p>The Wishlist menu lets a signed-in customer save products for later. A client uses it to power the &quot;save to wishlist&quot; heart icon, the wishlist page, and the &quot;move to cart&quot; action.</p><h2 id="when-you-use-it" tabindex="-1">When you use it <a class="header-anchor" href="#when-you-use-it" aria-label="Permalink to &quot;When you use it&quot;">​</a></h2><p>The wishlist is per-customer and scoped to the current channel. A customer can add a product (or toggle it on and off), list everything saved, view one item, move an item into the cart, remove an item, or clear the whole wishlist at once. The wishlist is a customer feature — it is not available to guests.</p><h2 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>GraphQL field</th><th>Description</th></tr></thead><tbody><tr><td>List the wishlist</td><td><a href="/api/graphql-api/shop/queries/get-wishlists.html"><code>wishlists</code></a></td><td>The customer&#39;s saved products, paginated.</td></tr><tr><td>View one item</td><td><a href="/api/graphql-api/shop/queries/get-wishlist.html"><code>wishlist</code></a></td><td>A single wishlist entry.</td></tr><tr><td>Add a product</td><td><a href="/api/graphql-api/shop/mutations/create-wishlist.html"><code>createWishlist</code></a></td><td>Save a product to the wishlist.</td></tr><tr><td>Toggle a product</td><td><a href="/api/graphql-api/shop/mutations/toggle-wishlist.html"><code>toggleWishlist</code></a></td><td>Add the product if absent, remove it if present.</td></tr><tr><td>Remove an item</td><td><a href="/api/graphql-api/shop/mutations/delete-wishlist.html"><code>deleteWishlist</code></a></td><td>Drop one saved product.</td></tr><tr><td>Move to cart</td><td><a href="/api/graphql-api/shop/mutations/move-wishlist-to-cart.html"><code>moveWishlistToCart</code></a></td><td>Move a saved product into the cart. Returns the updated <strong>cart</strong>.</td></tr><tr><td>Clear the wishlist</td><td><a href="/api/graphql-api/shop/mutations/delete-all-wishlists.html"><code>createDeleteAllWishlists</code></a></td><td>Remove every saved product in one call.</td></tr></tbody></table><p>Toggling reports a removal through <code>errors[]</code> rather than a success payload — see <a href="/api/graphql-api/shop/mutations/toggle-wishlist.html">Toggle Wishlist</a> before wiring a heart icon to it.</p><p>Every product returned by the catalog also carries an <code>isInWishlist</code> flag, so a listing page can show the saved state without reading the wishlist separately.</p><p>All Wishlist operations require a customer Bearer token — see <a href="/api/graphql-api/authentication.html">Authentication</a>.</p>',9)]))}const m=e(o,[["render",r]]);export{u as __pageData,m as default};
